ts\";a:3:{i:0;s:6:\"Butler\";i:1;s:10:\"HK Grotesk\";i:2;s:6:\"Roboto\";}s:5:\"icons\";a:3:{i:0;s:10:\"fa-regular\";i:1;s:9:\"fa-brands\";i:2;s:8:\"fa-solid\";}s:20:\"dynamic_elements_ids\";a:0:{}s:6:\"status\";s:4:\"file\";i:0;s:0:\"\";}');
/*!40000 ALTER TABLE `wp_postmeta` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `wp_posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_posts` (
  `ID` bigint unsigned NOT NULL AUTO_INCREMENT,
  `post_author` bigint unsigned NOT NULL DEFAULT '0',
  `post_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_date_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_title` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_excerpt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'publish',
  `comment_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'open',
  `ping_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'open',
  `post_password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `post_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `to_ping` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `pinged` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_modified_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content_filtered` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_parent` bigint unsigned NOT NULL DEFAULT '0',
  `guid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `menu_order` int NOT NULL DEFAULT '0',
  `post_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'post',
  `post_mime_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `comment_count` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`ID`),
  KEY `post_name` (`post_name`(191)),
  KEY `type_status_date` (`post_type`,`post_status`,`post_date`,`ID`),
  KEY `post_parent` (`post_parent`),
  KEY `post_author` (`post_author`),
  KEY `type_status_author` (`post_type`,`post_status`,`post_author`)
) ENGINE=InnoDB AUTO_INCREMENT=263 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `wp_posts` WRITE;
/*!40000 ALTER TABLE `wp_posts` DISABLE KEYS */;
INSERT INTO `wp_posts` VALUES (1,1,'2026-08-26 15:52:03','2026-08-26 15:52:03','<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->','Hello world!','','publish','open','open','','hello-world','','','2026-08-26 15:52:03','2026-08-26 15:52:03','',0,'http://localhost:8080/?p=1',0,'post','',1),(2,1,'2026-08-26 15:52:03','2026-08-26 15:52:03','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://localhost:8080/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Sample Page','','publish','closed','open','','sample-page','','','2026-08-26 15:52:03','2026-08-26 15:52:03','',0,'http://localhost:8080/?page_id=2',0,'page','',0),(3,1,'2026-08-26 15:52:03','2026-08-26 15:52:03','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: http://localhost:8080.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n','Privacy Policy','','draft','closed','open','','privacy-policy','','','2026-08-26 15:52:03','2026-08-26 15:52:03','',0,'http://localhost:8080/?page_id=3',0,'page','',0),(4,1,'2026-08-26 15:52:25','0000-00-00 00:00:00','','Auto Draft','','auto-draft','open','open','','','','','2026-08-26 15:52:25','0000-00-00 00:00:00','',0,'http://localhost:8080/?p=4',0,'post','',0),(5,1,'2026-08-26 15:56:31','2026-08-26 15:56:31','','Default Kit','','publish','closed','closed','','default-kit','','','2026-08-26 21:12:49','2026-08-26 21:12:49','',0,'http://localhost:8080/?p=5',0,'elementor_library','',0),(6,1,'2026-08-26 16:01:55','2026-08-26 16:01:55','','Elementor #6','','trash','closed','closed','','__trashed','','','2026-08-26 16:01:55','2026-08-26 16:01:55','',0,'http://localhost:8080/?page_id=6',0,'page','',0),(8,1,'2026-08-26 15:57:33','2026-08-26 15:57:33','{\"version\": 3, \"isGlobalStylesUserThemeJSON\": true }','Custom Styles','','publish','closed','closed','','wp-global-styles-muu-hotel','','','2026-08-26 15:57:33','2026-08-26 15:57:33','',0,'http://localhost:8080/?p=8',0,'wp_global_styles','',0),(9,1,'2026-08-26 16:01:28','2026-08-26 16:01:28','[muu_nav_lefttab]\n[muu_orange_shape\n    target=\".muu-hero-host\"\n    left=\"20%\"\n    top=\"12%\"\n    width=\"28%\"\n    rotate=\"0\"\n    flip_x=\"true\"\n    color=\"#ff6a00\"\n]													<img width=\"2047\" height=\"1024\" src=\"http://localhost:8080/wp-content/uploads/2026/08/hero.png\" alt=\"\" srcset=\"http://localhost:8080/wp-content/uploads/2026/08/hero.png 2047w, http://localhost:8080/wp-content/uploads/2026/08/hero-300x150.png 300w, http://localhost:8080/wp-content/uploads/2026/08/hero-1024x512.png 1024w, http://localhost:8080/wp-content/uploads/2026/08/hero-768x384.png 768w, http://localhost:8080/wp-content/uploads/2026/08/hero-1536x768.png 1536w\" sizes=\"(max-width: 2047px) 100vw, 2047px\" />																<h2>Discovery.</h2>															<img src=\"http://localhost:8080/wp-content/uploads/elementor/thumbs/discovery-rsichn2o07wedswsluad5r35sz32tyjq2l7r5wuqn2.jpg\" title=\"discovery\" alt=\"discovery\" loading=\"lazy\" />																<h2>muu</h2>					<h2>– LOREM IPSUM DOLOR \nSIT AMET, CONSECTETUR \nADIPISCING ELIT. PELLE\nNTESQUE VESTIBULUM \nLIBERO LOREM, EGET \nCURSUS TORTOR.</h2>		&nbsp;Muu is a new, unpretentious yet luxurious hotel brand that is built around a belief that happiness comes from being oneself. Through dynamic, artistic spaces that live and breathe with the whims of its guests, muu is personable, ever-changing and never boring.			<h2>Destination.</h2>					<h2>– THONG LO, BANGKOK’S<br>TRENDIEST DISTRICT</h2>		<p>Thong lo won’t disappoint when it comes to lifestyle and the things that <br />you can do in the area. There are countless restaurants, cafes, and bars <br />to visit whenever you desire!</p><p>There are many expats living in Thonglor and the neighbouring area of Ekamai, <br />so there are many international restaurants like Japanese and Italian. <br />Prefer local food? No problem, there are many street vendors and <br />Thai restaurants in Thonglor as well. Are you addicted to coffee or have <br />a sweet tooth? Maybe both? There is no shortage of options in Thonglor <br />when it comes to cafes. There are street style coffee places to the high-end <br />stylish cafes. You will find a lot of the younger crowd visiting the stylish <br />modern cafes and international restaurants.</p>			<h2>←</h2>					<h2>01 / 02</h2>					<h2>→</h2>															<img src=\"http://localhost:8080/wp-content/uploads/elementor/thumbs/destination-1-rsichjb2jrc95lyyagxxpm8b3lik9nuuzrxb9573nu.png\" title=\"destination-1\" alt=\"destination-1\" loading=\"lazy\" />																										<img src=\"http://localhost:8080/wp-content/uploads/elementor/thumbs/destination-2-rsichl6qxfetstw7zhr6ulr8ad9ap22bo18a7p4bbe.png\" title=\"destination-2\" alt=\"destination-2\" loading=\"lazy\" />																<h2>Offers.</h2>					<h2>– STAY</h2>					<h2>EAT</h2>					<h2>EXPERIENCE</h2>					<h2>ALL</h2>							\n							<h2>Staycation in the Bustling \nThonglor Neighborhood</h2>							\n				<p>Enjoy the vibrant city of Thonglor in your style. Start your day <br />with an Italian breakfast at Otto Italian Restaurant. Keep the <br />shopping mode on during the day at Eight Thonglor Shopping Mall. <br />Begin your exploration mode at night by walking along Thonglor <br />Street. MUU Bangkok, a part of Small Luxury Hotels of the World, <br />is an upscale lifestyle hotel in Thonglor, Bangkok. </p>			<h2>More about our MUU Bangkok Offers, reach </h2>							\n			<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M464 64H48C21.49 64 0 85.49 0 112v288c0 26.51 21.49 48 48 48h416c26.51 0 48-21.49 48-48V112c0-26.51-21.49-48-48-48zm0 48v40.805c-22.422 18.259-58.168 46.651-134.587 106.49-16.841 13.247-50.201 45.072-73.413 44.701-23.208.375-56.579-31.459-73.413-44.701C106.18 199.465 70.425 171.067 48 152.805V112h416zM48 400V214.398c22.914 18.251 55.409 43.862 104.938 82.646 21.857 17.205 60.134 55.186 103.062 54.955 42.717.231 80.509-37.199 103.053-54.947 49.528-38.783 82.032-64.401 104.947-82.653V400H48z\"></path></svg>			\n				<p>reservation.bangkok@muuhotels.com</p>					\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M224.1 141c-63.6 0-114.9 51.3-114.9 114.9s51.3 114.9 114.9 114.9S339 319.5 339 255.9 287.7 141 224.1 141zm0 189.6c-41.1 0-74.7-33.5-74.7-74.7s33.5-74.7 74.7-74.7 74.7 33.5 74.7 74.7-33.6 74.7-74.7 74.7zm146.4-194.3c0 14.9-12 26.8-26.8 26.8-14.9 0-26.8-12-26.8-26.8s12-26.8 26.8-26.8 26.8 12 26.8 26.8zm76.1 27.2c-1.7-35.9-9.9-67.7-36.2-93.9-26.2-26.2-58-34.4-93.9-36.2-37-2.1-147.9-2.1-184.9 0-35.8 1.7-67.6 9.9-93.9 36.1s-34.4 58-36.2 93.9c-2.1 37-2.1 147.9 0 184.9 1.7 35.9 9.9 67.7 36.2 93.9s58 34.4 93.9 36.2c37 2.1 147.9 2.1 184.9 0 35.9-1.7 67.7-9.9 93.9-36.2 26.2-26.2 34.4-58 36.2-93.9 2.1-37 2.1-147.8 0-184.8zM398.8 388c-7.8 19.6-22.9 34.7-42.6 42.6-29.5 11.7-99.5 9-132.1 9s-102.7 2.6-132.1-9c-19.6-7.8-34.7-22.9-42.6-42.6-11.7-29.5-9-99.5-9-132.1s-2.6-102.7 9-132.1c7.8-19.6 22.9-34.7 42.6-42.6 29.5-11.7 99.5-9 132.1-9s102.7-2.6 132.1 9c19.6 7.8 34.7 22.9 42.6 42.6 11.7 29.5 9 99.5 9 132.1s2.7 102.7-9 132.1z\"></path></svg>			\n				<p>muuhotels</p>					\n			<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M493.4 24.6l-104-24c-11.3-2.6-22.9 3.3-27.5 13.9l-48 112c-4.2 9.8-1.4 21.3 6.9 28l60.6 49.6c-36 76.7-98.9 140.5-177.2 177.2l-49.6-60.6c-6.8-8.3-18.2-11.1-28-6.9l-112 48C3.9 366.5-2 378.1.6 389.4l24 104C27.1 504.2 36.7 512 48 512c256.1 0 464-207.5 464-464 0-11.2-7.7-20.9-18.6-23.4z\"></path></svg>			\n				<p>: +66 (0) 2 090 9000</p>			<h2>SPECIAL OFFER ENQUIRY</h2>					<h2>←</h2>					<h2>01 / 02</h2>					<h2>→</h2>															<img src=\"http://localhost:8080/wp-content/uploads/elementor/thumbs/happenings-rsichoy75bafn9nbzu6uce504i9ih5hl3n35zpwlm6.png\" title=\"happenings\" alt=\"happenings\" loading=\"lazy\" />																<h2>Happenings.</h2>					<h2>– KODAWARI TSUKIJI,<br>AN IMMERSIVE FISH<br>MARKET EXPERIENCE</h2>		<p>Focusing on a short-circuit approach and the quality of its products, the friendly restaurant follows the Japanese philosophy of kodawari, to pursue perfection, to the letter.</p><p>The menu, hung from a clothes line, offers unusual dishes that showcase seafood. Five traditionally made ramen dishes are available with different toppings. In contrast to the typical starters like edamame and gyoza, the desserts surprise the taste buds. Scallop rice pudding, miso ice cream with crunchy pumpkin seeds… The flavour combinations are a success. As the food is prepared in an open kitchen, diners can watch the chefs at work, whether they are seated around a large raw-wood table or at the bar.</p>			<h2>MORE</h2>					<h2>←</h2>					<h2>01 / 02</h2>					<h2>→</h2>					<h2>STAY TUNE - SUBSCRIBE TO OUR NEWSLETTER</h2>					\n<form action=\"#\" method=\"post\" style=\"\ndisplay:flex;align-items:stretch;width:100%;border-bottom:2px solid rgba(255,255,255,.85);\nfont-family:\'HK Grotesk\',Arial,sans-serif;\">\n  <label for=\"muu-newsletter-email\" style=\"position:absolute;left:-9999px;\">Email</label>\n  <input id=\"muu-newsletter-email\" type=\"email\" name=\"email\" place